import type { ColorTokens } from "@/registry/themes";

/** Theme color token keys that can be used for the color prop */
export const THEME_COLOR_KEYS = [
  "foreground",
  "background",
  "muted",
  "mutedForeground",
  "primary",
  "primaryForeground",
  "border",
  "accent",
  "destructive",
  "success",
  "warning",
  "info",
] as const satisfies (keyof ColorTokens)[];

/** Resolves a color value: theme token key → hex, or raw CSS color as-is. */
export const resolveColor = (value: string, colors: ColorTokens): string => {
  const key = value as (typeof THEME_COLOR_KEYS)[number];
  return THEME_COLOR_KEYS.includes(key) ? colors[key] : value;
};

import type { ReactNode } from "react";

import { Fixed, View } from "./pdfcn-primitives";
import type { Style } from "./pdfcn-primitives";

export const MaybeFixed = ({
  fixed,
  position,
  wrap,
  style,
  children,
}: {
  fixed?: boolean;
  position: "header" | "footer";
  wrap?: boolean;
  style?: Style | Style[];
  children?: ReactNode;
}) => {
  const view = (
    <View wrap={wrap} style={style as never}>
      {children}
    </View>
  );
  if (!fixed) {
    return view;
  }
  return <Fixed position={position}>{view}</Fixed>;
};
